using ANLAbel.Core.Workflow;
using ANLAbel.Data.Workflow;
internal static class DocumentWorkflowStoreRegression { public static Task Run() { var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".jsonl"); try { var store=new DocumentWorkflowStore(path); store.Append("doc","hash",DocumentWorkflowState.Draft,DocumentWorkflowState.InReview,"",null); store.Append("doc","hash",DocumentWorkflowState.InReview,DocumentWorkflowState.Approved,"reviewer","ok"); var events=store.ReadValid(out var diagnostics); Require(events.Count==2 && diagnostics.Count==0 && events[0].Actor=="local operator","Audit must retain local actor and chain."); File.AppendAllText(path,"bad\n"); Require(store.ReadValid(out diagnostics).Count==2 && diagnostics.Count==1,"Corrupt tail must preserve valid prefix."); var template=Path.Combine(Path.GetTempPath(),"workflow-template.anlabel"); Require(DocumentWorkflowSidecar.GetDocumentId(template)==DocumentWorkflowSidecar.GetDocumentId(template),"Sidecar identity must be deterministic."); Require(DocumentWorkflowSidecar.GetStorePath(template).EndsWith(".anlabel.workflow.jsonl",StringComparison.Ordinal),"Sidecar must not mutate the template envelope."); } finally { if(File.Exists(path))File.Delete(path); } return Task.CompletedTask; } private static void Require(bool x,string m){if(!x)throw new InvalidOperationException(m);} }
